-- 220: Original BrillaPrep WASSCE BrillaPrep transitional Sculpture beta content blueprint questions, part 8.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_220_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_220_guard;
INSERT INTO _migration_220_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_029' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_6' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which preparation is essential before welding components into a metal sculpture?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Remove incompatible coatings locally and control fumes, fire, radiation and hot-work hazards","B. Cool the welded area immediately with bare wet hands to check alignment","C. Weld through unknown painted coatings if the joint initially looks clean","D. Use ordinary clear spectacles because the arc is visible only briefly"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Coatings and contamination are removed under controlled conditions. Extraction, welding screens, correct eye and body protection, fire watch and safe handling are planned before hot work begins. Therefore the correct answer is A: Remove incompatible coatings locally and control fumes, fire, radiation and hot-work hazards.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_6' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_029' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_220_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_030' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_6' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why are found-object surfaces cleaned and tested before adhesive assembly?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A strong adhesive removes the need to identify the joined materials","B. Existing oil can act as a primer because it keeps the joint flexible","C. A glossy coating proves the underlying object is chemically compatible","D. Contamination or weak coatings may stop the adhesive bonding to sound material"]' AND q.correct_answer IS 'D' AND q.explanation IS 'A connection is only as reliable as its surface layers. Cleaning, appropriate abrasion and a small compatibility trial reveal contamination, coating failure or damaging chemical reaction before final assembly. Therefore the correct answer is D: Contamination or weak coatings may stop the adhesive bonding to sound material.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_6' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_030' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_220_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_031' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_7' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is negative space in a sculpture?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The written interpretation positioned beside the sculpture","B. The hidden core inside a completely solid modelling mass","C. The intentionally shaped open space around or within solid forms","D. An unfinished patch that must be filled before display"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Openings and intervals shape silhouette, rhythm, movement and viewing paths. Negative space is therefore designed together with mass rather than treated as unused emptiness. Therefore the correct answer is C: The intentionally shaped open space around or within solid forms.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_7' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_031' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_220_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_sculpture_b004_032' AND NOT (q.topic_id IS 'topic_was_sculpture_b004_7' AND q.subject_id IS 'subj_wassce_sculpture' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How can gesture be strengthened in a group-figure relief without distorting anatomy?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Establish the action line, weight-bearing relationships and major anatomical landmarks before details","B. Finish facial features first and fit the body into the remaining area","C. Enlarge every moving limb equally while ignoring the torso and pelvis","D. Use identical upright poses for all figures and rely on texture for motion"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Gesture grows from the action line and the relation of head, rib cage, pelvis and supporting limbs. Checking these masses early preserves anatomical logic while allowing expressive emphasis. Therefore the correct answer is A: Establish the action line, weight-bearing relationships and major anatomical landmarks before details.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_sculpture_b004_7' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_sculpture_b004_032' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_029', 'topic_was_sculpture_b004_6', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'Which preparation is essential before welding components into a metal sculpture?', 'multiple_choice', NULL, '["A. Remove incompatible coatings locally and control fumes, fire, radiation and hot-work hazards","B. Cool the welded area immediately with bare wet hands to check alignment","C. Weld through unknown painted coatings if the joint initially looks clean","D. Use ordinary clear spectacles because the arc is visible only briefly"]', 'A', 'Coatings and contamination are removed under controlled conditions. Extraction, welding screens, correct eye and body protection, fire watch and safe handling are planned before hot work begins. Therefore the correct answer is A: Remove incompatible coatings locally and control fumes, fire, radiation and hot-work hazards.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_6', 'Identify', 'AO2', NULL, NULL, 'board_waec');
