INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_031', 'topic_was_sculpture_b004_7', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'What is negative space in a sculpture?', 'multiple_choice', NULL, '["A. The written interpretation positioned beside the sculpture","B. The hidden core inside a completely solid modelling mass","C. The intentionally shaped open space around or within solid forms","D. An unfinished patch that must be filled before display"]', 'C', 'Openings and intervals shape silhouette, rhythm, movement and viewing paths. Negative space is therefore designed together with mass rather than treated as unused emptiness. Therefore the correct answer is C: The intentionally shaped open space around or within solid forms.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_7', 'Identify', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_sculpture_b004_032', 'topic_was_sculpture_b004_7', 'subj_wassce_sculpture', 'exam_wassce', NULL, NULL, 'How can gesture be strengthened in a group-figure relief without distorting anatomy?', 'multiple_choice', NULL, '["A. Establish the action line, weight-bearing relationships and major anatomical landmarks before details","B. Finish facial features first and fit the body into the remaining area","C. Enlarge every moving limb equally while ignoring the torso and pelvis","D. Use identical upright poses for all figures and rely on texture for motion"]', 'A', 'Gesture grows from the action line and the relation of head, rib cage, pelvis and supporting limbs. Checking these masses early preserves anatomical logic while allowing expressive emphasis. Therefore the correct answer is A: Establish the action line, weight-bearing relationships and major anatomical landmarks before details.', 'medium', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_sculpture_b004_7', 'Explain', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-visual-arts-beta-004', 'automated_beta', 'beta', 'Original BrillaPrep transitional Sculpture practice aligned to WAEC Ghana examiner evidence and NaCCA curriculum context; not official WAEC examination material or a copied past paper.', 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf', 0, 1 FROM questions WHERE id IN ('q_was_sculpture_b004_029', 'q_was_sculpture_b004_030', 'q_was_sculpture_b004_031', 'q_was_sculpture_b004_032');
